import json,sys
first_cmd=None; first_err=None; verify_cmd=None
tool_ids={}
for raw in open(sys.argv[1]):
    try: ev=json.loads(raw.split("\t",1)[1])
    except Exception: continue
    if ev.get("type")=="assistant":
        for b in ev.get("message",{}).get("content",[]) or []:
            if isinstance(b,dict) and b.get("type")=="tool_use" and b.get("name")=="Bash":
                cmd=b.get("input",{}).get("command","")
                tool_ids[b.get("id")]=cmd
                if first_cmd is None: first_cmd=cmd
                if verify_cmd is None and any(k in cmd for k in ("tsc","test","npm","vitest","psql","migrat")): verify_cmd=cmd
    if ev.get("type")=="user":
        for b in ev.get("message",{}).get("content",[]) or []:
            if isinstance(b,dict) and b.get("type")=="tool_result":
                c=b.get("content","")
                if isinstance(c,list): c="".join(x.get("text","") for x in c if isinstance(x,dict))
                if first_err is None and any(k in str(c) for k in ("error","Error","No such file","not found","cannot","fail","Fail")):
                    first_err=str(c)[:400]
print("FIRST CMD:", repr(first_cmd)[:200] if first_cmd else "(none — no Bash)")
print("FIRST ERRORish RESULT:", repr(first_err)[:350] if first_err else "(none found)")
print("VERIFY CMD:", repr(verify_cmd)[:180] if verify_cmd else "(none)")
PY
done; done

