                u=ev.get("message",{}).get("usage",{}) or {}
                ot=int(u.get("output_tokens") or 0)
                for b in ev.get("message",{}).get("content",[]) or []:
                    if isinstance(b,dict) and b.get("type")=="tool_use" and str(b.get("name","")).startswith("mcp__sofar__"):
                        calls+=1; out+=ot
    return calls,out
